function parseBlocks(text){
  text=String(text||'');
  var lines=text.split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var blocks=[], errors=[], total=0;
  for(var i=0;i<lines.length;i++){
    var m=lines[i].match(/^(\d{1,2}:\d{2})\s*[-–]\s*(\d{1,2}:\d{2})\s*(.*)$/);
    if(!m){ errors.push('第 '+(i+1)+' 行格式应为 09:00-10:00 标签'); continue; }
    var h1=+m[1].split(':')[0], mi1=+m[1].split(':')[1], h2=+m[2].split(':')[0], mi2=+m[2].split(':')[1];
    if(h2*60+mi2 <= h1*60+mi1){ errors.push('第 '+(i+1)+' 行结束须晚于开始'); continue; }
    var min=(h2*60+mi2)-(h1*60+mi1);
    blocks.push({start:m[1], end:m[2], label:m[3]||('块'+(blocks.length+1)), minutes:min});
    total+=min;
  }
  return {blocks:blocks, errors:errors, totalMinutes:total, totalHours:Math.round(total/6)/10};
}
var EXPORTS={parseBlocks:parseBlocks};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TimeBlockForgePure = EXPORTS; }
